<?php
namespace App\Services;
use App\Models\{Employee,EmployeeSalaryAssignment,LeaveBalance,LeaveRequest,PayrollItem,PayrollRun,Payslip,SalaryComponent}; use App\Support\Decimal; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
final class HrPayrollService {
    public function requestLeave(array $data): LeaveRequest { return DB::transaction(function() use($data){$balance=LeaveBalance::where('tenant_id',$data['tenant_id'])->where('employee_id',$data['employee_id'])->where('leave_policy_id',$data['leave_policy_id'])->where('year',date('Y',strtotime($data['starts_on'])))->lockForUpdate()->firstOrFail();$remaining=Decimal::sub((string)$balance->entitled,(string)$balance->used,4);if(Decimal::compare((string)$data['days'],$remaining)>0)throw ValidationException::withMessages(['days'=>['The leave request exceeds the available balance.']]);return LeaveRequest::create([...$data,'state'=>'pending']);}); }
    public function approveLeave(LeaveRequest $request,string $reviewer): LeaveRequest { return DB::transaction(function()use($request,$reviewer){$request=LeaveRequest::whereKey($request->id)->lockForUpdate()->firstOrFail();if($request->state!=='pending')throw ValidationException::withMessages(['state'=>['Only pending leave requests can be approved.']]);$balance=LeaveBalance::where('tenant_id',$request->tenant_id)->where('employee_id',$request->employee_id)->where('leave_policy_id',$request->leave_policy_id)->where('year',$request->starts_on->year)->lockForUpdate()->firstOrFail();$remaining=Decimal::sub((string)$balance->entitled,(string)$balance->used,4);if(Decimal::compare((string)$request->days,$remaining)>0)throw ValidationException::withMessages(['days'=>['The leave balance changed; approval is no longer available.']]);$balance->update(['used'=>Decimal::add((string)$balance->used,(string)$request->days,4)]);$request->update(['state'=>'approved','reviewed_by'=>$reviewer,'reviewed_at'=>now()]);return $request;}); }
    public function createPayroll(array $data): PayrollRun { return DB::transaction(function()use($data){if($existing=PayrollRun::where('tenant_id',$data['tenant_id'])->where('idempotency_key',$data['idempotency_key'])->first())return $existing->load('items');$employees=Employee::where('tenant_id',$data['tenant_id'])->where('company_id',$data['company_id'])->where('status','active')->get();$run=PayrollRun::create([...$data,'state'=>'draft']);foreach($employees as $employee){$contract=$employee->contracts()->where('status','active')->whereDate('starts_on','<=',$data['period_ends_on'])->where(fn($q)=>$q->whereNull('ends_on')->orWhereDate('ends_on','>=',$data['period_starts_on']))->latest('starts_on')->first();if(!$contract)continue;$assignment=$employee->salaryAssignments()->with('structure')->whereDate('starts_on','<=',$data['period_ends_on'])->where(fn($q)=>$q->whereNull('ends_on')->orWhereDate('ends_on','>=',$data['period_starts_on']))->latest('starts_on')->first();$base=Decimal::normalize((string)$contract->base_salary);$allowances='0';$deductions='0';$breakdown=['base_salary'=>$base,'components'=>[]];if($assignment){$components=SalaryComponent::where('tenant_id',$data['tenant_id'])->where('salary_structure_id',$assignment->salary_structure_id)->get();foreach($components as $component){$value=Decimal::normalize((string)$component->value);if($component->calculation_type==='percentage')$value=Decimal::div(Decimal::mul($base,$value), '100');$component->kind==='deduction'?$deductions=Decimal::add($deductions,$value):$allowances=Decimal::add($allowances,$value);$breakdown['components'][]=['code'=>$component->code,'kind'=>$component->kind,'amount'=>$value];}}$gross=Decimal::add($base,$allowances);$net=Decimal::sub($gross,$deductions);$item=PayrollItem::create(['tenant_id'=>$data['tenant_id'],'payroll_run_id'=>$run->id,'employee_id'=>$employee->id,'gross_pay'=>$gross,'allowances'=>$allowances,'deductions'=>$deductions,'net_pay'=>$net,'calculation_breakdown'=>$breakdown]);Payslip::create(['tenant_id'=>$data['tenant_id'],'payroll_item_id'=>$item->id,'number'=>'PS-'.$run->id.'-'.Str::upper(Str::random(5)),'access_token_hash'=>hash('sha256',Str::random(40))]);}return $run->load('items');}); }
    public function transition(PayrollRun $run,string $to,string $actor):PayrollRun{$allowed=['draft'=>['review'],'review'=>['approved'],'approved'=>['finalized']];if(!in_array($to,$allowed[$run->state]??[],true))throw ValidationException::withMessages(['state'=>['Invalid payroll transition.']]);$run->update(match($to){'approved'=>['state'=>$to,'approved_by'=>$actor,'approved_at'=>now()],'finalized'=>['state'=>$to,'finalized_by'=>$actor,'finalized_at'=>now()],default=>['state'=>$to]});return $run->fresh('items');}
}
